"""Deterministic curvature caps at both ends of original circular pieces.

The selected one-sided chart derivative is ambiguous at a curvature break.
Positive-turn arcs constrain the normal band by their radius on the CLOSED
parameter interval, including both endpoints. These caps only tighten the
existing sampled bound; they do not modify any curve, sample or contact.
"""
from . import curved_junction_nodes as boundary

c=boundary.c
FLOAT_EPSILON=2.**-23


def apply(g,inp,geometry,owner,t,cap,*,compound=False,continuations=False,span_compounds=False,chain_sides=False):
    """Retain the smaller incident arc cap at a shared boundary knot.

    Eight float32 epsilons in normalized parameter cover the nested
    length/fraction round trips. This allowance is used only at explicitly
    retained curvature knots; it cannot weaken the preexisting cap. General
    cubic curvature and all non-arc clearance checks remain unchanged.
    """
    tolerance=8.*FLOAT_EPSILON*c.named(g,'st_cg_break','BOOLEAN')
    def include(previous,start,end,radius,sweep,enabled=1.):
        hit=enabled*g.math('GREATER_THAN',sweep,0.)*g.math('GREATER_THAN',radius,1e-8)
        hit=hit*g.math('GREATER_THAN',end,start)
        hit=hit*(1.-g.math('LESS_THAN',t,start-tolerance))*(1.-g.math('GREATER_THAN',t,end+tolerance))
        return g.math('MINIMUM',previous,c.choose(g,hit,radius,1e8))
    if chain_sides:
        pieces=c._select(g,inp.outputs['Chain Pieces'],g.math('COMPARE',c.named(g,'st_ca_owner','INT'),owner))
        geo=c._store(g,geometry,'_cg_closed_arc_cap',cap)
        ri=g.node('GeometryNodeRepeatInput','Closed support of every original arc')
        ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
        g.bind(geo,ri.inputs['Geometry']);g.bind(c._count(g,pieces),ri.inputs['Iterations'])
        at=c.V(g,ri.outputs['Iteration']);read=lambda key,kind='FLOAT':c._read(g,pieces,'st_ca_'+key,at,kind)
        total=g.math('MAXIMUM',read('total'),1e-12)
        start=read('distance')/total;end=(read('distance')+read('length'))/total
        value=include(c.named(g,'_cg_closed_arc_cap'),start,end,read('radius'),read('sweep'),
                      g.math('COMPARE',read('kind','INT'),1.))
        g.bind(c._store(g,ri.outputs['Geometry'],'_cg_closed_arc_cap',value),ro.inputs['Geometry'])
        return c._store(g,ro.outputs['Geometry'],'st_cg_curvature_cap',c.named(g,'_cg_closed_arc_cap'))

    corners=inp.outputs['Corners'];mouths=inp.outputs['Mouths']
    read=lambda key,kind='FLOAT':c._read(g,corners,key,owner,kind)
    nxt=g.math('MODULO',owner+1.,c._count(g,mouths))
    la=g.math('ABSOLUTE',c._read(g,mouths,'st_cj_parameter',owner)-read('st_cc_sa'))
    lb=g.math('ABSOLUTE',c._read(g,mouths,'st_cj_parameter',nxt)-read('st_cc_sb'))
    arcs=[]
    def arc(base,radius,sweep,enabled=1.):
        length=radius*g.math('ABSOLUTE',sweep)
        arcs.append((base,base+length,radius,sweep,enabled))
    def retained(table,at,base,enabled=1.):
        get=lambda key,kind='FLOAT':c._read(g,table,key,at,kind)
        kind=get('st_ct_kind','INT');radius=get('st_cc_radius');sweep=get('st_cc_sweep')
        line=g.math('COMPARE',kind,1.);pair=g.math('COMPARE',kind,2.)
        arc(base,radius,sweep,enabled*(1.-line))
        arc(base+radius*g.math('ABSOLUTE',sweep),radius,get('st_ct_sweep_b'),enabled*pair)
    if span_compounds:
        from . import curved_port_compound_charts as spans
        second,lengths,nose,bridge=spans.parts(g,corners,owner);l0,l1,l2=lengths
        total=la+l0+l1+l2+lb
        retained(corners,owner,la,1.-nose)
        retained(second,0,la+l0+l1,bridge)
        for base,radius,sweep in ((la,'st_cc_radius','st_pc_sweep_a'),
                (la+l0,'st_pc_join_radius','st_pc_sweep_join'),
                (la+l0+l1,'st_pc_second_radius','st_pc_sweep_b')):
            arc(base,read(radius),read(sweep),nose)
    elif compound:
        from . import curved_compound_nose_nodes as nose
        _,_,_,radii,sweeps,lengths=nose.arc_fields(g,corners,owner)
        total=la+sum(lengths)+lb;base=la
        for radius,sweep,length in zip(radii,sweeps,lengths):
            arc(base,radius,sweep);base=base+length
    elif continuations:
        from . import curved_continuation_nodes as continuation
        total=la+continuation.length(g,corners,owner)+lb
        retained(corners,owner,la)
    else:
        radius=read('st_cc_radius');sweep=read('st_cc_sweep')
        total=la+radius*g.math('ABSOLUTE',sweep)+lb;arc(la,radius,sweep)
    total=g.math('MAXIMUM',total,1e-12)
    for start,end,radius,sweep,enabled in arcs:
        cap=include(cap,start/total,end/total,radius,sweep,enabled)
    return c._store(g,geometry,'st_cg_curvature_cap',cap)


def replace_saved(root):
    """Copy saved dependencies and replace eligible samplers for qualification.

    This opt-in does not install a public asset or modify saved groups in place.
    """
    from . import curved_clearance_nodes as clearance
    memo={};replaced=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.name.startswith('Prochitecture Streets / Original curved boundary samples') and any(
                label in tree.name for label in (' / Curb continuations',' / Original span sides',' / Original chain sides')):
            options={key:label in tree.name for key,label in (
                ('include_knots',' with knots'),('tapered',' / Taper'),('compound',' / Compound arcs'),
                ('continuations',' / Curb continuations'),('port_paths',' / Original Section ports'),
                ('span_compounds',' / Original span sides'),('chain_sides',' / Original chain sides'),
                ('interpolation',' / Exact entrance rays'))}
            if not options['include_knots']:raise ValueError('Closed arc sampling requires retained knots')
            result=clearance.samples(**options,closed_arc_caps=True);replaced.append(tree.name)
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            changed=[(name,child) for name,child in children if tree.nodes[name].node_tree!=child]
            result=tree.copy() if changed else tree
            for name,child in changed:result.nodes[name].node_tree=child
        memo[tree]=result;return result
    result=[visit(tree) for tree in root] if isinstance(root,(list,tuple)) else visit(root)
    if not replaced:raise ValueError('No eligible original boundary sampler')
    return result,replaced
